package com.hbm.client.turret;
import com.hbm.client.gui.LegacyContainerScreen;
import com.hbm.machine.turret.*;
import java.util.*;
import net.minecraft.ChatFormatting;
import net.minecraft.client.gui.*;
import net.minecraft.client.gui.components.EditBox;
import net.minecraft.client.resources.sounds.SimpleSoundInstance;
import net.minecraft.network.chat.Component;
import net.minecraft.resources.ResourceLocation;
import net.minecraft.sounds.SoundEvents;
import net.minecraft.world.entity.player.Inventory;
import net.neoforged.neoforge.network.PacketDistributor;
/** Original 176x222 Sentry GUI, original sprites, hand-rendered half-scale whitelist and eleven original slots. */
public class SentryScreen<M extends TurretMenu> extends LegacyContainerScreen<M> {
    private EditBox field;private int index;
    public SentryScreen(M menu,Inventory inventory,Component title){this(menu,inventory,title,ResourceLocation.parse("hbm:textures/gui/weapon/gui_turret_sentry.png"));}
    protected SentryScreen(M menu,Inventory inventory,Component title,ResourceLocation background){super(menu,inventory,title,background,176,222);}
    private TurretBaseEntity turret(){return minecraft!=null&&minecraft.level!=null&&minecraft.level.getBlockEntity(menu.position) instanceof TurretBaseEntity entity?entity:null;}
    private List<String> names(){var item=menu.slots.getFirst().getItem();return item.getItem() instanceof TurretChipItem?TurretChipItem.names(item):List.of();}
    @Override protected void init(){super.init();field=new EditBox(font,leftPos+10,topPos+65,50,14,Component.translatable("gui.hbm.turret.whitelist"));field.setTextColor(-1);field.setTextColorUneditable(-1);field.setBordered(false);field.setMaxLength(25);addWidget(field);}
    @Override protected void renderLabels(GuiGraphics graphics,int mouseX,int mouseY){graphics.drawString(font,title,88-font.width(title)/2,6,4210752,false);graphics.drawString(font,playerInventoryTitle,8,128,4210752,false);var names=names();index=Math.max(0,Math.min(index,names.size()-1));Component selected=names.isEmpty()?Component.translatable("turret.none").withStyle(ChatFormatting.ITALIC):Component.literal(names.get(index));String text=field.getValue();int cursor=field.getCursorPosition();if(field.isFocused())text=text.substring(0,cursor)+(System.currentTimeMillis()%1000<500?" ":"||")+text.substring(cursor);graphics.pose().pushPose();graphics.pose().scale(.5F,.5F,1);graphics.drawString(font,selected,24,102,0x00ff00,false);graphics.drawString(font,text,24,138,0x00ff00,false);graphics.pose().popPose();}
    @Override protected void renderBg(GuiGraphics graphics,float partial,int mouseX,int mouseY){super.renderBg(graphics,partial,mouseX,mouseY);for(int[] button:new int[][]{{7,80,176,58},{43,80,194,58},{7,98,176,76},{43,98,194,76}})if(legacyInfoHovered(mouseX,mouseY,button[0],button[1],18,18))drawLegacyRegion(graphics,button[0],button[1],button[2],button[3],18,18);var turret=turret();if(turret==null)return;int power=(int)(turret.getPower()*53/turret.getMaxPower());if(power>0)drawLegacyRegion(graphics,152,97-power,194,52-power,16,power);if(turret.isOn)drawLegacyRegion(graphics,115,26,176,40,18,18);boolean[] flags={turret.targetPlayers,turret.targetAnimals,turret.targetMobs,turret.targetMachines};for(int i=0;i<4;i++)if(flags[i])drawLegacyRegion(graphics,8+i*14,30,176,i*10,10,10);int kills=turret.stattrak;if(kills>=36)drawLegacyRegion(graphics,77,50,176,120,63,6);else{for(int i=0;i<(kills+4)/5;i++){int remainder=Math.min(5,kills-i*5);if(remainder==5)drawLegacyRegion(graphics,77+i*9,50,194,94,9,6);else drawLegacyRegion(graphics,77+i*9,50,176,94,remainder*2,6);}}}
    @Override public void render(GuiGraphics graphics,int mouseX,int mouseY,float partial){super.render(graphics,mouseX,mouseY,partial);var turret=turret();if(turret==null)return;if(legacyInfoHovered(mouseX,mouseY,152,45,16,52))graphics.renderTooltip(font,Component.literal(com.hbm.item.battery.BatteryItem.shortNumber(turret.getPower())+"/"+com.hbm.item.battery.BatteryItem.shortNumber(turret.getMaxPower())+"HE"),mouseX,mouseY);boolean[] flags={turret.targetPlayers,turret.targetAnimals,turret.targetMobs,turret.targetMachines};String[] keys={"turret.players","turret.animals","turret.mobs","turret.machines"};for(int i=0;i<4;i++)if(legacyInfoHovered(mouseX,mouseY,8+i*14,30,10,10))graphics.renderTooltip(font,Component.translatable(keys[i],Component.translatable(flags[i]?"turret.on":"turret.off").withStyle(flags[i]?ChatFormatting.GREEN:ChatFormatting.RED)),mouseX,mouseY);
        if(menu.getCarried().isEmpty()&&legacyInfoHovered(mouseX,mouseY,79,62,54,54)){boolean show=true;for(int i=1;i<10;i++){var slot=menu.slots.get(i);if(slot.hasItem()&&isHovering(slot.x,slot.y,16,16,mouseX,mouseY)){show=false;break;}}if(show){var ammo=turret.displayedAmmo();if(!ammo.isEmpty()){int cycle=(int)((System.currentTimeMillis()%(1000L*ammo.size()))/1000);TurretAmmoTooltip.draw(graphics,font,ammo,cycle,mouseX,mouseY,width,height);}}}
    }
    private void click(){minecraft.getSoundManager().play(SimpleSoundInstance.forUI(SoundEvents.UI_BUTTON_CLICK,1));}
    private void send(int action,int value,String name){PacketDistributor.sendToServer(new TurretControl(menu.position,action,value,name));}
    @Override public boolean mouseClicked(double x,double y,int button){boolean handled=super.mouseClicked(x,y,button);field.setFocused(x>=field.getX()&&x<field.getX()+field.getWidth()&&y>=field.getY()&&y<field.getY()+field.getHeight());if(legacyInfoHovered(x,y,115,26,18,18)){click();send(0,0,"");return true;}for(int i=0;i<4;i++)if(legacyInfoHovered(x,y,8+i*14,30,10,10)){click();send(0,i+1,"");return true;}int count=names().size();if(count>0){if(legacyInfoHovered(x,y,7,80,18,18)){index=(index-1+count)%count;click();return true;}if(legacyInfoHovered(x,y,43,80,18,18)){index=(index+1)%count;click();return true;}}if(legacyInfoHovered(x,y,7,98,18,18)){click();if(!field.getValue().isEmpty()){send(1,0,field.getValue());field.setValue("");}return true;}if(legacyInfoHovered(x,y,43,98,18,18)){click();send(2,index,"");return true;}return handled||field.isFocused();}
    @Override public boolean keyPressed(int key,int scan,int modifiers){if(field.keyPressed(key,scan,modifiers))return true;if(field.isFocused()&&key!=256)return true;return super.keyPressed(key,scan,modifiers);}@Override public boolean charTyped(char character,int modifiers){return field.charTyped(character,modifiers)||super.charTyped(character,modifiers);}
}
